function makeLimiter(max: number, windowMs: number, clock: Clock): () => boolean {
  const hits: number[] = []
  return function allow(): boolean {
    const now = clock.now()
    while (hits.length > 0 && hits[0] <= now - windowMs) hits.shift()
    if (hits.length >= max) return false
    hits.push(now)
    return true
  }
}

let t = 0
const clock: Clock = { now: () => t }
const allow = makeLimiter(2, 1000, clock)
console.log(allow(), allow(), allow())   // true true false
t = 1000
console.log(allow())                     // true: the window slid, no sleeping needed

