solution:
interface Clock {
  now(): number
}

class FakeClock implements Clock {
  private time: number
  constructor(start = 0) {
    this.time = start
  }
  now(): number {
    return this.time
  }
  advance(ms: number): void {
    this.time += ms
  }
}

interface TtlCache<V> {
  get(key: string): V | undefined
  set(key: string, value: V): void
  size(): number
}

function createTtlCache<V>(ttlMs: number, clock: Clock): TtlCache<V> {
  const store = new Map<string, { value: V; expiresAt: number }>()
  const isLive = (expiresAt: number): boolean => clock.now() < expiresAt
  return {
    get(key) {
      const entry = store.get(key)
      if (entry === undefined) return undefined
      if (!isLive(entry.expiresAt)) {
        store.delete(key)
        return undefined
      }
      return entry.value
    },
    set(key, value) {
      store.set(key, { value, expiresAt: clock.now() + ttlMs })
    },
    size() {
      for (const [key, entry] of store) if (!isLive(entry.expiresAt)) store.delete(key)
      return store.size
    },
  }
}

type Op = ['set', string, number] | ['get', string] | ['advance', number] | ['size']

function simulateTtl(ttlMs: number, ops: Op[]): (number | null)[] {
  const clock = new FakeClock()
  const cache = createTtlCache<number>(ttlMs, clock)
  const out: (number | null)[] = []
  for (const op of ops) {
    switch (op[0]) {
      case 'set':
        cache.set(op[1], op[2])
        break
      case 'get':
        out.push(cache.get(op[1]) ?? null)
        break
      case 'advance':
        clock.advance(op[1])
        break
      case 'size':
        out.push(cache.size())
        break
    }
  }
  return out
}

The clock is the only source of time, so the driver's `FakeClock` fully controls expiry and the results are identical on every run. `set` records an absolute `expiresAt`, which makes overwriting a key restart its TTL for free. `get` and `size` both use one `isLive` rule (`now < expiresAt`), so the boundary is consistent: at exactly `ttlMs` the entry is gone, and a TTL of 0 means nothing is ever readable. Expired entries are removed lazily, on `get` and on `size`, so `get` and `set` are O(1) and `size` is O(n). The generic `V` lets the same cache hold strings or user objects, and the type checks confirm that `get` returns `V | undefined` and that a clock without `now()` is rejected.

