    const name = raw.trim()
    if (name !== '') out.push(greet(name))
  }
  return out
}

type Spy<A extends unknown[], R> = ((...args: A) => R) & {
  calls: A[]
  results: R[]
}

function createSpy<A extends unknown[], R>(impl: (...args: A) => R): Spy<A, R> {
  const calls: A[] = []
  const results: R[] = []
  const spy = (...args: A): R => {
    calls.push(args)
    const result = impl(...args)
    results.push(result)
    return result
  }
  return Object.assign(spy, { calls, results })
}

function spyGreet(names: string[]): { calls: [string][]; results: string[] } {
  const greet = createSpy((name: string) => `hi ${name}`)
  greetAll(names, greet)
  return { calls: greet.calls, results: greet.results }
}

type Rng = () => number

// mulberry32: a 32-bit state stepped by a constant, then scrambled into [0, 1).
function mulberry32(seed: number): Rng {
  let state = seed >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let t = state
    t = Math.imul(t ^ (t >>> 15), t | 1)
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61)
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

function shuffle<T>(items: readonly T[], rng: Rng): T[] {
  const out = items.slice()
  for (let i = out.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1))
    ;[out[i], out[j]] = [out[j], out[i]]
  }
  return out
}

function seededShuffle(items: string[], seed: number): string[] {
  return shuffle(items, mulberry32(seed))
}

